// 订单模块：提供接口并将请求交给业务层。
package com.fandazi.feature.order;
import com.fandazi.feature.payment.PaymentService; import jakarta.validation.Valid; import java.util.List; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/orders") public class OrderController { private final OrderService orders; private final PaymentService payments; public OrderController(OrderService orders,PaymentService payments){this.orders=orders;this.payments=payments;} public record CreateRequest(@jakarta.validation.constraints.NotNull(message="购物车不能为空") Long cartDraftId,@jakarta.validation.constraints.NotNull(message="地址不能为空") Long addressId){} @GetMapping public List<OrderResponse> list(@AuthenticationPrincipal Long userId){return orders.listResponses(userId);}@PostMapping public ResponseEntity<OrderResponse> create(@AuthenticationPrincipal Long userId,@RequestHeader("Idempotency-Key") String key,@Valid @RequestBody CreateRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(orders.createResponse(userId,new CreateOrderCommand(request.cartDraftId(),request.addressId(),key)));}@PostMapping("/{id}/pay") public OrderResponse pay(@AuthenticationPrincipal Long userId,@PathVariable Long id,@RequestHeader("Idempotency-Key") String key){return payments.payResponse(userId,id,key);}@GetMapping("/{id}") public OrderResponse get(@AuthenticationPrincipal Long userId,@PathVariable Long id){return orders.getResponse(userId,id);} }
